import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"Packages","description":"","frontmatter":{},"headers":[],"relativePath":"packages/index.md","filePath":"packages/index.md","lastUpdated":1793736494000}'),d={name:"packages/index.md"};function i(n,e,c,r,p,l){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h1><p>kernl has four packages under the <code>@kernl</code> scope, not yet published to npm (see <a href="#install">Install</a>). Three are pure contracts and engines with zero framework dependencies; one composes them with kehto and applesauce. The shell app at <code>apps/web</code> is not published.</p><table tabindex="0"><thead><tr><th>Package</th><th>Version</th><th>Role</th><th>Dependencies</th><th>Peer dependencies</th></tr></thead><tbody><tr><td><a href="./guard"><code>@kernl/guard</code></a></td><td><code>0.1.0</code></td><td>Ingress flood control, visibility gate, focus-aware firewall, CSP profile, nested-frame lock, mitigation descriptions.</td><td><code>@kehto/firewall</code></td><td><code>@napplet/core</code></td></tr><tr><td><a href="./messaging"><code>@kernl/messaging</code></a></td><td><code>0.1.0</code></td><td>Messaging provider contract, registry, composite direct-message adapter, in-memory backend.</td><td>none</td><td><code>@napplet/core</code> (the <code>Dm*</code> wire types)</td></tr><tr><td><a href="./bridges"><code>@kernl/bridges</code></a></td><td><code>0.1.0</code></td><td>Locator parsing, bridge contract, registry, HTTP bridge with SSRF policy.</td><td>none</td><td>none</td></tr><tr><td><a href="./core"><code>@kernl/core</code></a></td><td><code>0.1.0</code></td><td>Composition root over kehto and applesauce: adapters, applet resolution, mount plan, consent summaries, layouts, persistence.</td><td>the three above, <code>@kehto/*</code>, <code>applesauce-*</code>, <code>rxjs</code></td><td><code>@napplet/core</code>, <code>@napplet/nap</code>, <code>@napplet/shim</code>, <code>nostr-tools</code> (required by kehto and applesauce; never imported)</td></tr></tbody></table><h2 id="shared-rules" tabindex="-1">Shared rules <a class="header-anchor" href="#shared-rules" aria-label="Permalink to &quot;Shared rules&quot;">​</a></h2><ul><li>ESM only, TypeScript strict, <code>verbatimModuleSyntax</code>. Each package ships <code>dist/index.js</code> and <code>dist/index.d.ts</code> with <code>sideEffects: false</code>.</li><li>Every public export has JSDoc with <code>@param</code>, <code>@returns</code> and <code>@example</code>, and appears in the <a href="./../reference/api">API reference</a>.</li><li>Streams in <code>@kernl/core</code> are rxjs <code>Observable</code>s (<code>session$</code>, <code>guard.events$</code>, <code>grants.changes$</code>, <code>relays.changes$</code>, <code>AppletHandle.status$</code>); unsubscribe the <code>Subscription</code> they return. <code>MessagingBackend.subscribe</code> returns <code>{ subscriptionId }</code>, which you pass to <code>unsubscribe</code>. Thrown errors carry a stable prefixed reason: <code>denied:</code>, <code>invalid:</code>, <code>unavailable:</code>; the full list is in <a href="./../reference/errors">Error reasons</a>.</li><li>No published package imports <code>nostr-tools</code> directly, and no published package depends on a UI framework. <code>pnpm check:deps</code> enforces both.</li><li>Behaviour is specified in Gherkin under each package&#39;s <code>features/</code> and run by vitest with 100% coverage over <code>src</code>.</li></ul><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h2><p>All packages are <code>0.x</code>. A breaking change is a <code>minor</code> bump; everything else is a <code>patch</code>. Releases are managed with changesets: one changeset per package whose shipped output changed. <code>@kernl/core</code> depends on the other three with <code>workspace:^</code>, so a release of a leaf package produces a patch of core.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>The <code>@kernl/*</code> packages are not yet published to npm; <code>pnpm add @kernl/core</code> fails with a not-found error. During the alpha the source repository is private, and the packages are used from a clone of it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># in a clone of the kernl source repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>pnpm build</code> writes each package&#39;s <code>dist/</code>, which is what <code>main</code>, <code>types</code> and <code>exports</code> point at. Then add your code as a workspace package (under <code>packages/</code> or <code>apps/</code>, the globs in <code>pnpm-workspace.yaml</code>) and depend on what you need with the workspace protocol, as <code>apps/web</code> does:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@kernl/core&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workspace:^&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@kernl/guard&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workspace:^&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Run <code>pnpm install</code> again after editing the manifest so pnpm links the workspace packages. <code>@kernl/core</code> pulls the other three in. Install a leaf package alone when you want its contract without kehto and applesauce, for example <code>@kernl/guard</code> to test an applet against the limits, or <code>@kernl/messaging</code> to write a provider.</p>`,13)])])}const g=a(d,[["render",i]]);export{k as __pageData,g as default};
